# ──────────────── Step 1: Comment invalid lines ─────────────────
def comment_invalid_text(input_path, output_path):
    with open(input_path, "r", encoding="utf-8") as f:
        content = f.read()

    commented_lines = []
    in_comment = False
    
    for line in content.splitlines():
        stripped = line.strip()
        
        # Track if we're inside a comment block
        if '<!--' in line:
            in_comment = True
        if '-->' in line:
            in_comment = True  # This line is part of comment
            commented_lines.append(line)
            in_comment = False
            continue
            
        # If inside comment, keep as is
        if in_comment:
            commented_lines.append(line)
        # Strip embedded XML declarations and RDF wrapper tags (LLM wraps each block in its own document)
        elif stripped.startswith("<?xml") or stripped.startswith("<rdf:RDF") or stripped.startswith("</rdf:RDF>"):
            commented_lines.append(f"<!-- {stripped} -->")
        # If line is invalid (not XML and not empty), comment it
        # LIMITATION: This check is line-by-line. If an XML element's text content spans
        # multiple lines, continuation lines (which don't start with "<") will be wrongly
        # commented out. In practice this is not an issue because LLM output for structured
        # data keeps element content on a single line, but be aware if output format changes.
        elif stripped and not stripped.startswith("<"):
            commented_lines.append(f"<!-- {stripped} -->")
        else:
            commented_lines.append(line)

    with open(output_path, "w", encoding="utf-8") as f:
        f.write("\n".join(commented_lines))

comment_invalid_text(rdf_input_path, rdf_output_path)

