# ──────────────── Step 5: RDF Cleaner / Validation ─────────────────
BK_NS = "https://gams.uni-graz.at/o:depcha.bookkeeping#"

def split_multinode_properties_generic(tree: ET._ElementTree):
    changed = False
    fixed_count = 0
    root = tree.getroot()

    # List of parent tags to process
    parent_tags = ["transfers", "ows", "consistsOf"]  # Add more if needed
    # List of child element types to check for multinode properties
    child_types = ["Money", "Commodity", "Service", "Right", "Debt"]  # Add more if needed

    for tag_name in parent_tags:
        xpath_expr = f"//bk:{tag_name}"
        for prop in root.xpath(xpath_expr, namespaces={"bk": BK_NS}):
            # Keep only element children and skip comments/PIs/etc.
            element_children = [c for c in prop if isinstance(getattr(c, "tag", None), str)]
            # Check for any child type in the list
            for child_type in child_types:
                children = [c for c in element_children if ET.QName(c).localname == child_type]
                if len(children) <= 1:
                    continue
                parent = prop.getparent()
                if parent is None:
                    continue
                attrib_copy = dict(prop.attrib)
                idx = parent.index(prop)
                # Remove original property and reinsert split ones
                parent.remove(prop)
                for offset, child in enumerate(children):
                    new_prop = ET.Element(prop.tag, attrib=attrib_copy, nsmap=prop.nsmap)
                    new_prop.append(child)
                    parent.insert(idx + offset, new_prop)
                changed = True
                fixed_count += 1
                break  # Only split once per parent tag

    return changed, fixed_count


# Back-reference words the LLM sometimes writes as if they were a person id, e.g.
# "dedimus eidem ..." -> <bk:to rdf:resource=".../context:arec#eidem"/>. Such a URI names
# nobody — it is the Latin word for "the same one", not an identity. The ground truth never
# uses these, so they are reset to #anonymous, which is also what the coreference pass
# (step 4) needs: it may only resolve a slot that is marked as unknown.
#
# This is a safety net, not the primary fix — the JSONtoRDF prompt should not produce these
# in the first place. It stays because a prompt is a tendency, not a guarantee.
#
# Deliberately EXCLUDED are all one- and two-letter forms and anything that could be read as
# a Roman numeral or a coin abbreviation ("ii" = 2, "is", "id", "ea", "ei", "eo", "se", "hi").
# The demonstratives (hic/ille) are left out too: they are not used as agent ids in practice
# and their short forms carry the same collision risk. Verified against 759 distinct agent
# URIs across all books — the list below matches only genuine back-references.
_BACKREF_AGENTS = {
    # idem, eadem, idem — "the same"
    "idem", "eidem", "eadem", "eodem", "eundem", "eandem", "earundem", "eorundem",
    "eiusdem", "iidem", "isdem", "iisdem", "eisdem", "eaedem", "eosdem", "easdem",
    # ipse — "himself/herself/themselves"
    "ipse", "ipsa", "ipsum", "ipsius", "ipsi", "ipsam", "ipso", "ipsorum", "ipsarum",
    "ipsis", "ipsos", "ipsas",
    # is, ea, id (longer forms only) and the reflexive
    "eius", "eum", "eam", "eorum", "earum", "eis", "eos", "eas", "sibi", "sese", "secum",
    # "the aforementioned"
    "predictus", "predicto", "predicti", "prefatus", "prefato",
    "dictus", "dicto", "dicti", "supradictus", "supradicto",
    # German equivalents, for the vernacular account books
    "derselbe", "demselben", "denselben", "dieselbe", "demselbigen", "denselbigen",
}
_AGENT_TAGS = ("from", "to", "by", "credit", "debit")


def normalize_backreference_agents(tree):
    """Reset agent references that are merely a back-reference word to #anonymous.
    Only the fragment after '#' changes, so each URI keeps its own base."""
    res_attr = "{http://www.w3.org/1999/02/22-rdf-syntax-ns#}resource"
    hits = {}
    xp = " | ".join(f"//*[local-name()='{t}']" for t in _AGENT_TAGS)
    for el in tree.xpath(xp):
        uri = el.get(res_attr)
        if not uri or "#" not in uri:
            continue
        base, frag = uri.rsplit("#", 1)
        if frag.lower() in _BACKREF_AGENTS:
            el.set(res_attr, f"{base}#anonymous")
            key = f"{ET.QName(el).localname}:{frag}"
            hits[key] = hits.get(key, 0) + 1
    if hits:
        total = sum(hits.values())
        detail = ", ".join(f"{k}={v}" for k, v in sorted(hits.items()))
        print(f"✅ {total} back-reference agent(s) reset to #anonymous ({detail})")
    else:
        print("✅ No back-reference words used as agent ids.")
    return hits


def sanitize_rdfxml(input_path, output_path):
    parser = ET.XMLParser(remove_blank_text=False, resolve_entities=False)
    tree = ET.parse(input_path, parser)
    changed, fixed_count = split_multinode_properties_generic(tree)
    normalize_backreference_agents(tree)
    tree.write(output_path, encoding="utf-8", xml_declaration=True, pretty_print=True)
    if changed:
        print(f"✅ Sanitized RDF/XML written: {output_path} ({fixed_count} fixes applied)")
    else:
        print(f"✅ RDF/XML sanitized (no fixes needed): {output_path}")

